for i, r in enumerate(range(35,41)):
    pres = 12 + i
    cons = 19 + i
    cap = 26 + i
    for c in range(8,13):
        col = openpyxl.utils.get_column_letter(c)
        ws.cell(r,c).value = f'=({col}{pres}-{col}{cons})/{col}{cap}*100'

# Statistics rows based on labels: 42 Minimum, 43 Maximum, 44 Median, 45 Simple mean, 46 25th percentile, 47 75th percentile.
stat_formulas = {
    42: 'MIN',
    43: 'MAX',
    44: 'MEDIAN',
    45: 'AVERAGE',
}
for c in range(8,13):
    col = openpyxl.utils.get_column_letter(c)
    for r, fn in stat_formulas.items():
        ws.cell(r,c).value = f'={fn}({col}35:{col}40)'
    ws.cell(46,c).value = f'=PERCENTILE.INC({col}35:{col}40,0.25)'
    ws.cell(47,c).value = f'=PERCENTILE.INC({col}35:{col}40,0.75)'
    ws.cell(50,c).value = f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'

# Verify in-memory no non-target cell value changed.
