import openpyxl, os
orig='/root/data/workbook.xlsx'
res='/root/output/result.xlsx'
wo=openpyxl.load_workbook(orig, data_only=False)
wr=openpyxl.load_workbook(res, data_only=False)
assert wo.sheetnames == wr.sheetnames, (wo.sheetnames, wr.sheetnames)
# target cells whose values are intentionally changed
targets=set()
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13): targets.add(('Task',r,c))
for r in range(35,41):
    for c in range(8,13): targets.add(('Task',r,c))
for r in range(42,48):
    for c in range(8,13): targets.add(('Task',r,c))
for c in range(8,13): targets.add(('Task',50,c))

value_diffs=[]
style_diffs=[]
merged_diffs=[]
dim_diffs=[]
for s in wo.sheetnames:
    a,b=wo[s],wr[s]
    if (a.max_row,a.max_column)!=(b.max_row,b.max_column):
        dim_diffs.append((s,(a.max_row,a.max_column),(b.max_row,b.max_column)))
    if [str(x) for x in a.merged_cells.ranges] != [str(x) for x in b.merged_cells.ranges]:
        merged_diffs.append((s,[str(x) for x in a.merged_cells.ranges],[str(x) for x in b.merged_cells.ranges]))
    maxr=max(a.max_row,b.max_row); maxc=max(a.max_column,b.max_column)
    for r in range(1,maxr+1):
        for c in range(1,maxc+1):
            ca,cb=a.cell(r,c),b.cell(r,c)
            if ca.value != cb.value and (s,r,c) not in targets:
                value_diffs.append((s,ca.coordinate,ca.value,cb.value))
            # Compare formatting-related style proxies on all cells including targets.
            attrs=(ca.style_id, ca.number_format, ca.font.copy(), ca.fill.copy(), ca.border.copy(), ca.alignment.copy(), ca.protection.copy())
            battrs=(cb.style_id, cb.number_format, cb.font.copy(), cb.fill.copy(), cb.border.copy(), cb.alignment.copy(), cb.protection.copy())
            if attrs != battrs:
                style_diffs.append((s,ca.coordinate,ca.style_id,cb.style_id))

formula_missing=[]
for s,r,c in targets:
    v=wr[s].cell(r,c).value
    if not (isinstance(v,str) and v.startswith('=')):
        formula_missing.append((s,wr[s].cell(r,c).coordinate,v))
print('comparison original -> result')
print('sheet names unchanged:', wo.sheetnames)
print('dimension diffs:', dim_diffs)
print('merged diffs:', merged_diffs)
print('non-target value diffs:', len(value_diffs), value_diffs[:5])
print('style diffs:', len(style_diffs), style_diffs[:5])
print('target formula cells:', len(targets), 'missing/non-formula:', formula_missing)
assert not dim_diffs and not merged_diffs and not value_diffs and not style_diffs and not formula_missing
print('preservation verification passed')
